insert into public.hospitals (name, city, state, country, operational_status, medisync_tier, tier_basis, catalog_metadata) select 'Sri Ramachandra Medical Centre', 'Chennai', 'Tamil Nadu', 'India', 'ACTIVE', 'Tier 1', 'By Hospital Type', jsonb_build_object('ownership','Private (Deemed University)','district','Chennai','notes','Teaching + tertiary hospital','source','Tamil_Nadu_Hospitals_3_Tier.xlsx') where not exists (select 1 from public.hospitals h where lower(h.name)=lower('Sri Ramachandra Medical Centre') and lower(coalesce(h.city,''))=lower('Chennai'));
